---level2 script---local isPlayingDemo = falselocal countFail = 0local isSkip = truelocal hasViewedStory = global.getBool("lvl2_b1")if not hasViewedStory or not game.isRestart() then	repeat		if hasViewedStory then dialog.setSkipEnabled(true) end		game.setUserInputEnabled(false)		role.setIdleActionEnabled(false)		script.delay(1)		sound.play("42-2")		if dialog.show("Level2-1", faceWeixiao) ==1 then break end		role.lookLeftRight()		script.delay(3)		sound.play("50-1")		if dialog.show("Level2-2", faceZhoumei) ==1 then break end		sound.play("60-1")		if dialog.show("Level2-3", faceQidao) ==1 then break end		if dialog.show("Level2-4", faceRenzhen) ==1 then break end		game.showTutorialDiagram(2)		if dialog.showMinTime("Level2-5", faceWeixiao,6.5) ==1 then break end		game.showTutorialDiagram(0)		game.setUserInputEnabled(true)				--set story viewed flag        global.setBool("lvl2_b1")		game.restartTiming()		role.setIdleActionEnabled(true)				isSkip = false			until trueendif isSkip then	camera.gotoRole()	camera.setFollowRoleMode(true)	dialog.setSkipEnabled(false)	game.resumeLogic()	game.showTutorialDiagram(0)	game.setUserInputEnabled(true)	role.setIdleActionEnabled(true)	game.restartTiming()endonRoleDied = function()    countFail = countFail + 1    game.setUserInputEnabled(false)    if countFail <= 1 then		sound.play("51-2")        dialog.show("Level1-12", faceBujie)    else		sound.play("58-1")        dialog.show("Level1-13", faceShengqi)    end    game.setUserInputEnabled(true)    role.loadState()end